const stoneSoldierSheet=new Image();stoneSoldierSheet.assetSrc='assets/stone-soldier-v1.png';
function beginStoneSoldier(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'stoneShieldThrust',bespoke:true,windup:.9,origin:{x:e.x,y:e.y},angle:Math.atan2(p.y-e.y,p.x-e.x),shield:false,locked:false,thrust:false};}
function stoneShieldContains(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,angle=Math.atan2(dy,dx)-a.angle;angle=Math.atan2(Math.sin(angle),Math.cos(angle));return Math.hypot(dx,dy)<=140+1e-8&&Math.abs(angle)<=Math.PI*65/180+1e-8;}
function stoneThrustContains(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,along=dx*Math.cos(a.thrustAngle)+dy*Math.sin(a.thrustAngle),side=-dx*Math.sin(a.thrustAngle)+dy*Math.cos(a.thrustAngle);return along>=0&&along<=280+1e-8&&Math.abs(side)<=22+1e-8;}
const stoneSoldierAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r9e2')return stoneSoldierAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='stoneShieldThrust'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=180&&clear){beginStoneSoldier(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,76*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,24)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.shield&&e.elapsed>=.9){a.shield=true;e.struck=true;if(stoneShieldContains(a,p)&&lineClear(a.origin,p)){let hp=p.hp;hurt(32);if(!dead&&p.hp<hp)moveActor(p,Math.cos(a.angle)*90,Math.sin(a.angle)*90);}playSound('impact',e.x,e.y);}
 if(!dead&&!a.locked&&e.elapsed>=1.2){a.locked=true;a.thrustAngle=Math.atan2(p.y-a.origin.y,p.x-a.origin.x);a.windup=2.1;e.struck=false;e.facing=Math.cos(a.thrustAngle)-Math.sin(a.thrustAngle)<0?-1:1;}
 if(!dead&&!a.thrust&&e.elapsed>=2.1){a.thrust=true;e.struck=true;if(stoneThrustContains(a,p)&&lineClear(a.origin,p))hurt(88);playSound('impact',e.x,e.y);}
 if(e.elapsed>=3.2){e.attack=null;e.state='idle';e.t=2.6;}
};
const stoneSoldierDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r9e2'||!stoneSoldierSheet.complete||!stoneSoldierSheet.naturalWidth||!stoneSoldierSheet.naturalHeight)return stoneSoldierDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='stoneShieldThrust')f={row:2,col:e.elapsed<.9?0:e.elapsed<1.2?1:e.elapsed<2.1?0:e.elapsed<2.35?2:3};let q=project(e.x,e.y),sw=stoneSoldierSheet.naturalWidth/4,sh=stoneSoldierSheet.naturalHeight/3,w=210,h=w*sh/sw,anchor=[[.935,.935,.935,.935],[.94,.895,.945,.945],[.91,.95,.93,.90]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,stoneSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(stoneSoldierSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const stoneSoldierSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r9e2'?180:stoneSoldierSizeBase(e);
const stoneSoldierGroundBase=drawGroundEffects;drawGroundEffects=()=>{stoneSoldierGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r9e2'):enemies)){let a=e.attack;if(e.species!=='r9e2'||e.hp<=0||a?.pattern!=='stoneShieldThrust'||!visibleAt(e.x,e.y))continue;if(e.elapsed>=2.35){groundRing(e.x,e.y,35,'#9fc9bb',1);continue;}let q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle='#d7b77c22';ctx.strokeStyle='#dec79e';ctx.lineWidth=2;ctx.beginPath();if(!a.locked){ctx.moveTo(0,0);ctx.arc(0,0,140,a.angle-Math.PI*65/180,a.angle+Math.PI*65/180);ctx.closePath();}else{ctx.rotate(a.thrustAngle);ctx.rect(0,-22,280,44);}ctx.fill();ctx.stroke();ctx.restore();}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r9e2',animateEnemy,drawRegionEnemy);
